const delegate = { save(id) { db.write(id); }, load(id) { return db.read(id); } };

const counting = Object.create(delegate);     // delegate becomes the [[Prototype]]
counting.save = function (id) {               // own property shadows the delegate
  this.count = (this.count ?? 0) + 1;
  return delegate.save(id);                   // explicit forward
};
